  const groups = d => { const g = d.length === 8 ? [4, 4] : d.length === 9 ? [3, 3, 3] : d.length === 10 ? [3, 3, 4] : d.length === 11 ? [3, 4, 4] : [4, 4, 4]; let o = [], k = 0; g.forEach(n => { if (k < d.length) { o.push(d.slice(k, k + n)); k += n; } }); if (k < d.length) o.push(d.slice(k)); return o.join(' '); };
